&._is-active {
  &>.dropdown-button svg {
    transform: rotate(180deg) !important;
  }

  &>.dropdown-list {
    max-height: 1260px !important;
    opacity: 1 !important;
    transform: translateY(0) !important;
    pointer-events: auto !important;
  }
}

&._is-filled {
  &>.dropdown-button {
    border-color: var(--accent) !important;
  }
}

min-width: 100px;

width: 100%;
display: flex;
align-items: center;
justify-content: space-between;
gap: 8px;
padding: 10px 12px;
border-radius: 4px;
border: 1px solid color-mix(in srgb, var(--navy-800) 37%, transparent);
outline: none;
transition: all 200ms cubic-bezier(0.4, 0, 0.2, 1);
height: 40px;
background: color-mix(in srgb, var(--navy-800) 17%, transparent);
backdrop-filter: blur(14px);
-webkit-backdrop-filter: blur(14px);
cursor: pointer;
transition: all .2s ease;
color: var(--sky-200);

&:hover {
  border: 1px solid var(--sky-500);
svg {
  color: var(--sky-500);
}
}

position: absolute;
left: 0;
right: 0;
top: calc(100% + 8px);
margin: 0;
padding: 6px 0;
list-style: none;
border-radius: 10px;
border: 1px solid var(--sky-500);
background: color-mix(in srgb, var(--navy-800) 17%, transparent);
