-webkit-backdrop-filter: blur(14px);
overflow: hidden;
max-height: 0;
opacity: 0;
transform: translateY(-8px);
pointer-events: none;
transition: all .2s ease;
z-index: 100000;

padding: 8px 12px;
font-size: 14px;
cursor: pointer;
color: var(--sky-500);
transition: all .2s ease;

&:hover {
  background: var(--slate-300);
  color: var(--sky-800);
}

display: flex;
flex-direction: row;
align-items: center;
gap: 5px;

position: relative;
display: flex;

width: max-content;
flex-direction: row;
align-items: center;

display: inline-block;
margin: 0 0 0 40px;
cursor: pointer;
transition: all 0.2s;
font-size: 14px;
color: var(--sky-200);

&::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  border-radius: 4px;
  width: 20px;
  height: 20px;
  transform: translateY(-50%);
