/* @component: form-avatar */
(function () {
  function initUpload() {
    const containers = document.querySelectorAll('.form-avatar');

    containers.forEach(container => {
      if (container.dataset.initialized) return;

      const dropZone = container.querySelector('.upload-dropzone');
      const fileInput = container.querySelector('input[type="file"]');
      const fileInfo = container.querySelector('.file-info');
      const fileNameDisplay = container.querySelector('.file-name');
      const removeBtn = container.querySelector('.remove-file');
      const avatarIcon = container.querySelector('.avatar-icon');
      const avatarPreview = container.querySelector('.avatar-preview');
      const changeBtn = container.querySelector('.change-btn');
      const fileInfoThumb = container.querySelector('.file-info-thumb');

      if (!dropZone || !fileInput) return;

      ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(eventName => {
        dropZone.addEventListener(eventName, preventDefaults, false);
        document.body.addEventListener(eventName, preventDefaults, false);
      });

      ['dragenter', 'dragover'].forEach(eventName => dropZone.addEventListener(eventName, () => dropZone.classList.add('drag-over'), false));
      ['dragleave', 'drop'].forEach(eventName => dropZone.addEventListener(eventName, () => dropZone.classList.remove('drag-over'), false));

      dropZone.addEventListener('drop', (e) => handleFiles(e.dataTransfer.files, processCoverPhoto), false);
      fileInput.addEventListener('change', (e) => handleFiles(e.target.files, processCoverPhoto));
      dropZone.addEventListener('click', (e) => {
        if (e.target !== fileInput) fileInput.click();
      });

      if (removeBtn) {
        removeBtn.addEventListener('click', (e) => {
          e.stopPropagation();
          resetCoverUpload();
        });
      }

      if (changeBtn) {
        changeBtn.addEventListener('click', () => {
          if (fileInput.files && fileInput.files.length > 0) {
            const file = fileInput.files[0];
            if (file.type.startsWith('image/')) {
              processAvatarPhoto(file);
              resetCoverUpload();
            } else {
              alert('Please select an image file in the Cover Photo area.');
            }
          } else {
            alert('Please upload an image to the "Cover photo" area below first.');
          }
        });
      }

      function preventDefaults(e) {
        e.preventDefault();
        e.stopPropagation();
      }

      function handleFiles(files, callback) {
        if (files.length > 0) {
          const file = files[0];
          if (file.type.startsWith('image/')) {
            callback(file);
          } else {
            alert('Please upload an image file (PNG, JPG, GIF).');
          }
        }
      }

      function processCoverPhoto(file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          if (fileInfoThumb) fileInfoThumb.src = e.target.result;
          if (fileNameDisplay) fileNameDisplay.textContent = file.name;
          if (fileInfo) fileInfo.style.display = 'flex';
        };
        reader.readAsDataURL(file);
      }

      function resetCoverUpload() {
        fileInput.value = '';
        if (fileInfo) fileInfo.style.display = 'none';
        if (fileNameDisplay) fileNameDisplay.textContent = '';
        if (fileInfoThumb) fileInfoThumb.src = '';
      }

      function processAvatarPhoto(file) {
        const reader = new FileReader();
        reader.onload = (e) => {
          if (avatarPreview) {
            avatarPreview.src = e.target.result;
            avatarPreview.style.display = 'block';
          }
          if (avatarIcon) avatarIcon.style.display = 'none';
        };
        reader.readAsDataURL(file);
      }

      container.dataset.initialized = 'true';
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initUpload);
  } else {
    initUpload();
  }

  setTimeout(initUpload, 300);
})();

